<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use App\Support\HotelContext;
use Carbon\Carbon;
class BookingController extends Controller {
    private function hotel($slug){$h=DB::table('hotels')->where('public_slug',$slug)->where('public_booking',true)->first();abort_unless($h,404);\App\Services\SubscriptionAccess::ensure($h,true);return $h;}
    private function dates(Request $r,$h){$today=now($h->timezone)->toDateString();$r->merge(['arrival'=>$r->input('arrival',$today),'departure'=>$r->input('departure',Carbon::parse($today)->addDay()->toDateString()),'adults'=>$r->input('adults',1)]);$r->validate(['arrival'=>'required|date_format:Y-m-d|after_or_equal:'.$today]);return $r->validate(['arrival'=>'required|date_format:Y-m-d|after_or_equal:'.$today,'departure'=>'required|date_format:Y-m-d|after:arrival|before_or_equal:'.Carbon::parse($r->input('arrival'))->addDays(90)->toDateString(),'adults'=>'required|integer|min:1|max:20']);}
    public function index(Request $r,string $slug){$hotel=$this->hotel($slug);try{$d=$this->dates($r,$hotel);}catch(ValidationException $e){if($r->expectsJson())throw $e;return redirect('/booking/'.$slug)->withErrors($e->errors());}$rooms=DB::table('rooms')->where('hotel_id',$hotel->id)->where('out_of_service',false)->where('capacity','>=',$d['adults'])->whereNotIn('id',DB::table('reservations')->where('hotel_id',$hotel->id)->whereIn('status',['confirmed','checked_in'])->where('arrival','<',$d['departure'])->where('departure','>',$d['arrival'])->select('room_id'))->orderBy('rate')->orderBy('id')->get()->groupBy(fn($room)=>json_encode([$room->type,$room->rate,$room->capacity,$room->facilities]))->map(function($group){$room=$group->first();$room->available_count=$group->count();return $room;})->values();return response()->view('public-booking',['hotel'=>$hotel,'dates'=>$d,'rooms'=>$rooms,'nights'=>(int)Carbon::parse($d['arrival'])->diffInDays($d['departure']),'requestKey'=>(string)Str::uuid()])->header('Cache-Control','no-store');}
    public function store(Request $r,string $slug){$h=$this->hotel($slug);$dates=$this->dates($r,$h);$d=$r->validate(['room_id'=>'required|integer','guest'=>'required|string|max:120','phone'=>'required|string|max:30','email'=>'required|email|max:200','quoted_rate'=>'required|integer|min:0','request_key'=>'required|uuid']);
        $b=DB::transaction(function()use($h,$dates,$d){DB::table('hotels')->where('id',$h->id)->lockForUpdate()->first();$existing=DB::table('reservations')->where('hotel_id',$h->id)->where('request_key',$d['request_key'])->first();if($existing)return $existing;
            $room=DB::table('rooms')->where('hotel_id',$h->id)->where('id',$d['room_id'])->lockForUpdate()->first();abort_unless($room,404);
            if($room->out_of_service||$room->capacity<$dates['adults']||$room->rate!=$d['quoted_rate']||DB::table('reservations')->where('room_id',$room->id)->whereIn('status',['confirmed','checked_in'])->where('arrival','<',$dates['departure'])->where('departure','>',$dates['arrival'])->exists())throw ValidationException::withMessages(['room_id'=>'Kamar atau harga telah berubah. Periksa ketersediaan kembali.']);
            $cost=(int)Carbon::parse($dates['arrival'])->diffInDays($dates['departure'])*$room->rate;$token=(string)Str::uuid();$id=DB::table('reservations')->insertGetId([...$dates,'hotel_id'=>$h->id,'room_id'=>$room->id,'guest'=>$d['guest'],'phone'=>$d['phone'],'code'=>'WEB-'.Str::upper(Str::random(8)),'source'=>'Website','total'=>$cost,'room_total'=>$cost,'nightly_rate'=>$room->rate,'public_token'=>$token,'request_key'=>$d['request_key'],'notes'=>'Booking langsung. Kontak email: '.$d['email'],'created_at'=>now(),'updated_at'=>now()]);DB::table('audit_logs')->insert(['hotel_id'=>$h->id,'action'=>'Booking publik dibuat','entity'=>'reservations','entity_id'=>$id,'created_at'=>now()]);return DB::table('reservations')->find($id);
        },3);return redirect('/booking/'.$slug.'/confirmation/'.$b->public_token);
    }
    public function confirmation(Request $r,string $slug,string $token){$h=$this->hotel($slug);$b=DB::table('reservations')->where('hotel_id',$h->id)->where('public_token',$token)->first();abort_unless($b,404);return response()->view('booking-confirmation',['hotel'=>$h,'booking'=>$b])->header('Cache-Control','no-store')->header('Referrer-Policy','no-referrer');}
    public function settings(Request $r){$c=new HotelContext($r);$c->authorize('hotel.manage');$d=$r->validate(['enabled'=>'required|boolean']);$slug=$c->hotel->public_slug?:Str::slug($c->hotel->name).'-'.Str::lower(Str::random(6));DB::table('hotels')->where('id',$c->hotel->id)->update(['public_booking'=>$d['enabled'],'public_slug'=>$slug]);$c->audit('Booking publik diatur','hotels',$c->hotel->id);return response()->json(['message'=>'Pengaturan booking langsung diperbarui.']);}
}
